#include <functional>
#include <iostream>

int main() {
    auto cuadrado = [](int x) { return x * x; };
    std::cout << cuadrado(5) << '\n';   // 25

    int base = 10;
    auto sumar_base = [base](int x) { return base + x; };
    std::cout << sumar_base(5) << '\n'; // 15

    std::function<int(int)> operacion;  // vacia, como un puntero nulo
    if (!operacion) {
        std::cout << "sin operacion\n";
    }
    operacion = cuadrado;
    std::cout << operacion(4) << '\n';  // 16
    return 0;
}

