#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> datos{1, 2, 3, 4, 5, 6};
    std::vector<int> pares;

    std::copy_if(datos.begin(), datos.end(), std::back_inserter(pares),
        [](int n) { return n % 2 == 0; });

    std::transform(pares.begin(), pares.end(), pares.begin(),
        [](int n) { return n * n; });

    const int total = std::accumulate(pares.begin(), pares.end(), 0);

    for (int n : pares) {
        std::cout << n << ' ';   // 4 16 36
    }
    std::cout << '\n' << total << '\n'; // 56
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Alumno {
    std::string nombre;
    double nota;
};

int main() {
    std::vector<Alumno> alumnos{
        {"ana", 7.5},
        {"luis", 6.0},
        {"eva", 7.5},
        {"tom", 4.0},
    };

    std::sort(alumnos.begin(), alumnos.end(),
        [](const Alumno& a, const Alumno& b) {
            if (a.nota != b.nota) return a.nota > b.nota;
            return a.nombre < b.nombre;
        });

    for (const auto& [nombre, nota] : alumnos) {
        std::cout << nombre << ' ' << nota << '\n';
    }

    const auto aprobados = std::count_if(alumnos.begin(), alumnos.end(),
        [](const Alumno& a) { return a.nota >= 6.0; });
    std::cout << "aprobados: " << aprobados << '\n'; // 3
    return 0;
}

